/**
 * What the runtime knows about this project's entities.
 */
final readonly class Catalogue implements EntityCatalogue
{
    public function __construct(
        private ContainerInterface $container,
    ) {
    }

    /**
     * @return list<string>
     */
    public function entities(): array
    {
        return ['Author', 'Comment', 'Post', 'Tag'];
    }

    /**
     * @return Hydrator<object>
     */
    public function hydrator(string $entity): Hydrator
    {
        $service = match ($entity) {
            'Author' => $this->container->get(AuthorHydrator::class),
            'Comment' => $this->container->get(CommentHydrator::class),
            'Post' => $this->container->get(PostHydrator::class),
            'Tag' => $this->container->get(TagHydrator::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof Hydrator);

        return $service;
    }

    public function verifiers(string $entity): EntityVerifiers
    {
        $service = match ($entity) {
            'Author' => $this->container->get(AuthorVerifiers::class),
            'Comment' => $this->container->get(CommentVerifiers::class),
            'Post' => $this->container->get(PostVerifiers::class),
            'Tag' => $this->container->get(TagVerifiers::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntityVerifiers);

        return $service;
    }

    public function triggers(string $entity): EntityTriggers
    {
        $service = match ($entity) {
            'Author' => $this->container->get(AuthorTriggers::class),
            'Comment' => $this->container->get(CommentTriggers::class),
            'Post' => $this->container->get(PostTriggers::class),
            'Tag' => $this->container->get(TagTriggers::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntityTriggers);

        return $service;
    }

    private function readPoliciesPostReadPolicies(): EntityReadPolicies
    {
        $policies = $this->container->get(PostReadPolicies::class);

        assert($policies instanceof PostReadPolicies);

        return $policies;
    }

    public function readPolicies(string $entity): EntityReadPolicies
    {
        return match ($entity) {
            'Author' => new NoPolicies(),
            'Comment' => new NoPolicies(),
            'Post' => $this->readPoliciesPostReadPolicies(),
            'Tag' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    private function writePoliciesPostWritePolicies(): EntityWritePolicies
    {
        $policies = $this->container->get(PostWritePolicies::class);

        assert($policies instanceof PostWritePolicies);

        return $policies;
    }

    public function writePolicies(string $entity): EntityWritePolicies
    {
        return match ($entity) {
            'Author' => new NoPolicies(),
            'Comment' => new NoPolicies(),
            'Post' => $this->writePoliciesPostWritePolicies(),
            'Tag' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return array<string, string> "Entity.edge" => target entity
     */
    public function edgeTargets(): array
    {
        return [
            'Comment.author' => 'Author',
            'Post.comments' => 'Comment',
            'Post.tags' => 'Tag',
        ];
    }

    /**
     * @return array<string, string> "Entity.field" => declared type
     */
    public function fieldTypes(): array
    {
        return [
            'Post.price' => 'Money',
        ];
    }

    /**
     * @return list<string>
     */
    public function fieldNames(string $entity): array
    {
        return match ($entity) {
            'Author' => ['name'],
            'Comment' => ['body'],
            'Post' => ['createdAt', 'updatedAt', 'postId', 'slug', 'title', 'price', 'status', 'visibility', 'publishedAt'],
            'Tag' => ['label'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredFields(string $entity): array
    {
        return match ($entity) {
            'Author' => ['name'],
            'Comment' => ['body'],
            'Post' => ['title', 'status'],
            'Tag' => ['label'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredEdges(string $entity): array
    {
        return match ($entity) {
            'Author' => [],
            'Comment' => [],
            'Post' => [],
            'Tag' => [],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function uniqueFields(string $entity): array
    {
        return match ($entity) {
            'Author' => [],
            'Comment' => [],
            'Post' => ['postId'],
            'Tag' => ['label'],
            default => [],
        };
    }

    /**
     * @return array<string, Managed> "Entity.field" => policy
     */
    public function managedFields(): array
    {
        return [
            'Post.createdAt' => Managed::Created,
            'Post.updatedAt' => Managed::Modified,
        ];
    }

    /**
     * @return list<DeletionRule>
     */
    public function deletionRules(string $entity): array
    {
        return match ($entity) {
            'Author' => AuthorDeleter::rules(),
            'Comment' => CommentDeleter::rules(),
            'Post' => PostDeleter::rules(),
            'Tag' => TagDeleter::rules(),
            default => [],
        };
    }

    public function finder(string $entity): object
    {
        $finder = match ($entity) {
            'Post' => $this->container->get(PostFinder::class),
            default => throw new RuntimeException(sprintf('%s declares no queries.', $entity)),
        };

        assert(is_object($finder));

        return $finder;
    }

    public function mutatorFor(string $entity, MutationBuffer $buffer): object
    {
        return match ($entity) {
            'Author' => new AuthorMutator($buffer),
            'Comment' => new CommentMutator($buffer),
            'Post' => new PostMutator($buffer, $this->resolve(PostPublishAction::class)),
            'Tag' => new TagMutator($buffer),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return list<string>
     */
    public function queryArguments(string $entity, string $query): array
    {
        return match ($entity . '.' . $query) {
            'Post.published' => ['limit'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function actionArguments(string $entity, string $action): array
    {
        return match ($entity . '.' . $action) {
            'Post.publish' => ['at'],
            default => [],
        };
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeAuthorInputActionArguments(string $action, array $args): array
    {
        $input = $this->container->get(AuthorInput::class);

        assert($input instanceof AuthorInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeCommentInputActionArguments(string $action, array $args): array
    {
        $input = $this->container->get(CommentInput::class);

        assert($input instanceof CommentInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodePostInputActionArguments(string $action, array $args): array
    {
        $input = $this->container->get(PostInput::class);

        assert($input instanceof PostInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeTagInputActionArguments(string $action, array $args): array
    {
        $input = $this->container->get(TagInput::class);

        assert($input instanceof TagInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeActionArguments(string $entity, string $action, array $args): array
    {
        return match ($entity) {
            'Author' => $this->decodeAuthorInputActionArguments($action, $args),
            'Comment' => $this->decodeCommentInputActionArguments($action, $args),
            'Post' => $this->decodePostInputActionArguments($action, $args),
            'Tag' => $this->decodeTagInputActionArguments($action, $args),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @param array<string, mixed> $input
     */
    public function apply(string $entity, MutationBuffer $buffer, array $input): void
    {
        $applier = match ($entity) {
            'Author' => $this->container->get(AuthorInput::class),
            'Comment' => $this->container->get(CommentInput::class),
            'Post' => $this->container->get(PostInput::class),
            'Tag' => $this->container->get(TagInput::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert(is_object($applier) && method_exists($applier, 'apply'));

        $applier->apply($buffer, $input);
    }

    /**
     * Everything the application must implement before it can start.
     *
     * @return list<string>
     */
    public function contracts(): array
    {
        return ['App\\Elephentity\\Pattern\\Auditable\\Contract\\AuditableOwnerReadPolicy', 'App\\Elephentity\\Post\\Contract\\PostAuditTrigger', 'App\\Elephentity\\Post\\Contract\\PostNoBackwardsWritePolicy', 'App\\Elephentity\\Post\\Contract\\PostPriceVerifier', 'App\\Elephentity\\Post\\Contract\\PostPublishAction', 'App\\Elephentity\\Post\\Contract\\PostPublishedQuery', 'App\\Elephentity\\Post\\Contract\\PostReindexTrigger', 'App\\Elephentity\\Post\\Contract\\PostReporterReadPolicy', 'App\\Elephentity\\Type\\MoneyReadProcessor', 'App\\Elephentity\\Type\\MoneyWriteProcessor'];
    }

    /**
     * @template T of object
     * @param class-string<T> $class
     * @return T
     */
    private function resolve(string $class): object
    {
        $service = $this->container->get($class);

        assert($service instanceof $class);

        return $service;
    }
}

namespace App\Elephentity\Comment;

use App\Elephentity\Author\Author;
use App\Elephentity\Post\Post;
use Eleph\Runtime\Identity\EntityId;
use Eleph\Runtime\Query\EdgeLoader;

/**
 * Comment, as stored.
 */
final class Comment
{
    private function __construct(
        private readonly EntityId $id,
        private readonly EdgeLoader $edges,
        private readonly string $body,
    ) {
    }

    public function getId(): EntityId
    {
        return $this->id;
    }

    public function getBody(): string
    {
        return $this->body;
    }

    /**
     * @return Author|null
     */
    public function getAuthor(): ?Author
    {
        $related = $this->edges->toOne('Comment', $this->id, 'author');
        assert(null === $related || $related instanceof Author);

        return $related;
    }

    /**
     * The Post whose "comments" points here.
     *
     * @return Post|null
     */
    public function getPost(): ?Post
    {
        $related = $this->edges->inverseToOne('Post', 'comments', $this->id);
        assert(null === $related || $related instanceof Post);

        return $related;
    }

    public static function of(EntityId $id, EdgeLoader $edges, string $body): self
    {
        return new self($id, $edges, $body);
    }
}

