namespace App\Elephentity\Comment;

use Eleph\Runtime\Identity\Identifier;
use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Query\ValueDecoder;
use InvalidArgumentException;

/**
 * Turns raw input into pending Comment changes.
 */
final readonly class CommentInput
{
    public function __construct(
        private ValueDecoder $decode,
    ) {
    }

    private function body(mixed $value): ?string
    {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Comment.body');
    }

    /**
     * @return list<Identifier>
     */
    private function author(mixed $value): array
    {
        if (null === $value) {
            return [];
        }

        return [$this->decode->id($value, 'Comment.author')];
    }

    /**
     * Only what the caller supplied. A key that is absent is left alone,
     * which is what makes a partial update partial.
     *
     * @param array<string, mixed> $input
     */
    public function apply(MutationBuffer $buffer, array $input): void
    {
        if (array_key_exists('body', $input)) {
            $buffer->set('body', $this->body($input['body']));
        }

        if (array_key_exists('author', $input)) {
            $buffer->edge('author')->set($this->author($input['author']));
        }
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeAction(string $action, array $args): array
    {
        return match ($action) {

            default => throw new InvalidArgumentException(sprintf('Unknown action %s.', $action)),
        };
    }
}

