namespace App\Elephentity\Post;

use App\Elephentity\Pattern\Auditable\Contract\AuditableOwnerReadPolicy;
use App\Elephentity\Post\Contract\PostReporterReadPolicy;
use Eleph\Runtime\Policy\EntityReadPolicies;
use Eleph\Runtime\Policy\PolicyDecision;
use Eleph\Runtime\Policy\PolicyOutcome;
use Eleph\Runtime\Policy\Viewer;

final readonly class PostReadPolicies implements EntityReadPolicies
{
    public function __construct(
        private AuditableOwnerReadPolicy $ownerPolicy,
        private PostReporterReadPolicy $reporterPolicy,
    ) {
    }

    public function isEmpty(): bool
    {
        return false;
    }

    public function decide(object $entity, Viewer $viewer): PolicyDecision
    {
        assert($entity instanceof Post);
        $decision = $this->ownerPolicy->decide($entity, $viewer);
        if (PolicyOutcome::Skip !== $decision->outcome) {
            return $decision->withPolicy('owner');
        }

        $decision = $this->reporterPolicy->decide($entity, $viewer);
        if (PolicyOutcome::Skip !== $decision->outcome) {
            return $decision->withPolicy('reporter');
        }

        return PolicyDecision::allow('')->withPolicy('terminal');
    }
}

namespace App\Elephentity\Post;

use App\Elephentity\Post\Contract\PostAuditTrigger;
use App\Elephentity\Post\Contract\PostReindexTrigger;
use Eleph\Runtime\Mutation\EntityTriggers;
use Eleph\Runtime\Mutation\MutationContext;
use Eleph\Runtime\Trigger\TriggerEvent;
use Eleph\Runtime\Trigger\TriggerPhase;

/**
 * Runs Post's triggers, in the order the spec declares them.
 */
final readonly class PostTriggers implements EntityTriggers
{
    public function __construct(
        private PostAuditTrigger $auditTrigger,
        private PostReindexTrigger $reindexTrigger,
    ) {
    }

    public function dispatch(TriggerPhase $phase, TriggerEvent $event, MutationContext $context): void
    {
        $typed = PostMutationContext::of($context);

        if (TriggerPhase::PostCommit === $phase && in_array($event, [TriggerEvent::Create, TriggerEvent::Update], true)) {
            $this->auditTrigger->handle($typed);
        }

        if (TriggerPhase::PostCommit === $phase && in_array($event, [TriggerEvent::Create, TriggerEvent::Update], true)) {
            $this->reindexTrigger->handle($typed);
        }
    }
}

