use App\Elephentity\Comment\CommentVerifiers;
use App\Elephentity\Comment\CommentWritePolicies;
use App\Elephentity\Pattern\Auditable\Contract\AuditableOwnerReadPolicy;
use App\Elephentity\Post\Contract\PostAuditTrigger;
use App\Elephentity\Post\Contract\PostNoBackwardsWritePolicy;
use App\Elephentity\Post\Contract\PostPriceVerifier;
use App\Elephentity\Post\Contract\PostPublishedQuery;
use App\Elephentity\Post\Contract\PostReindexTrigger;
use App\Elephentity\Post\Contract\PostReporterReadPolicy;
use App\Elephentity\Post\PostFinder;
use App\Elephentity\Post\PostHydrator;
use App\Elephentity\Post\PostInput;
use App\Elephentity\Post\PostReadPolicies;
use App\Elephentity\Post\PostTriggers;
use App\Elephentity\Post\PostVerifiers;
use App\Elephentity\Post\PostWritePolicies;
use App\Elephentity\Tag\TagHydrator;
use App\Elephentity\Tag\TagInput;
use App\Elephentity\Tag\TagReadPolicies;
use App\Elephentity\Tag\TagTriggers;
use App\Elephentity\Tag\TagVerifiers;
use App\Elephentity\Tag\TagWritePolicies;
use App\Elephentity\Type\MoneyReadProcessor;
use Closure;
use Eleph\Runtime\Query\ValueDecoder;
use Psr\Container\ContainerInterface;

/**
 * Every generated class this project's container must be able to build.
 */
final class Wiring
{
    /**
     * The hand-written Contract bindings are not here: BootCheck enforces those
     * separately, against contracts() on the catalogue.
     *
     * @return array<class-string, Closure(ContainerInterface): object>
     */
    public static function registrations(): array
    {
        return [
            AuthorHydrator::class => static fn (ContainerInterface $c): object => new AuthorHydrator(self::resolve($c, ValueDecoder::class)),
            AuthorInput::class => static fn (ContainerInterface $c): object => new AuthorInput(self::resolve($c, ValueDecoder::class)),
            AuthorTriggers::class => static fn (ContainerInterface $c): object => new AuthorTriggers(),
            AuthorVerifiers::class => static fn (ContainerInterface $c): object => new AuthorVerifiers(),
            AuthorReadPolicies::class => static fn (ContainerInterface $c): object => new AuthorReadPolicies(),
            AuthorWritePolicies::class => static fn (ContainerInterface $c): object => new AuthorWritePolicies(),
            CommentHydrator::class => static fn (ContainerInterface $c): object => new CommentHydrator(self::resolve($c, ValueDecoder::class)),
            CommentInput::class => static fn (ContainerInterface $c): object => new CommentInput(self::resolve($c, ValueDecoder::class)),
            CommentTriggers::class => static fn (ContainerInterface $c): object => new CommentTriggers(),
            CommentVerifiers::class => static fn (ContainerInterface $c): object => new CommentVerifiers(),
            CommentReadPolicies::class => static fn (ContainerInterface $c): object => new CommentReadPolicies(),
            CommentWritePolicies::class => static fn (ContainerInterface $c): object => new CommentWritePolicies(),
            PostHydrator::class => static fn (ContainerInterface $c): object => new PostHydrator(self::resolve($c, ValueDecoder::class), self::resolve($c, MoneyReadProcessor::class)),
            PostInput::class => static fn (ContainerInterface $c): object => new PostInput(self::resolve($c, ValueDecoder::class), self::resolve($c, MoneyReadProcessor::class)),
            PostTriggers::class => static fn (ContainerInterface $c): object => new PostTriggers(self::resolve($c, PostAuditTrigger::class), self::resolve($c, PostReindexTrigger::class)),
            PostVerifiers::class => static fn (ContainerInterface $c): object => new PostVerifiers(self::resolve($c, PostPriceVerifier::class)),
            PostReadPolicies::class => static fn (ContainerInterface $c): object => new PostReadPolicies(self::resolve($c, AuditableOwnerReadPolicy::class), self::resolve($c, PostReporterReadPolicy::class)),
            PostWritePolicies::class => static fn (ContainerInterface $c): object => new PostWritePolicies(self::resolve($c, PostNoBackwardsWritePolicy::class)),
            PostFinder::class => static fn (ContainerInterface $c): object => new PostFinder(self::resolve($c, PostPublishedQuery::class)),
            TagHydrator::class => static fn (ContainerInterface $c): object => new TagHydrator(self::resolve($c, ValueDecoder::class)),
            TagInput::class => static fn (ContainerInterface $c): object => new TagInput(self::resolve($c, ValueDecoder::class)),
            TagTriggers::class => static fn (ContainerInterface $c): object => new TagTriggers(),
            TagVerifiers::class => static fn (ContainerInterface $c): object => new TagVerifiers(),
            TagReadPolicies::class => static fn (ContainerInterface $c): object => new TagReadPolicies(),
            TagWritePolicies::class => static fn (ContainerInterface $c): object => new TagWritePolicies(),
        ];
    }

    /**
     * @template T of object
     * @param class-string<T> $class
     * @return T
     */
    private static function resolve(ContainerInterface $c, string $class): object
    {
        $service = $c->get($class);

        assert($service instanceof $class);

        return $service;
    }
}
